from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    rules: ルール辞書の順序付きリスト
    urls:  URL文字列のリスト

    戻り値:
        書き換え後のURLのリスト。
        block に該当したURLは None。
    """

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        # 完全一致
        if not match_value.startswith("*."):
            return host == match_value

        # *.example.com は example.com 自体には適合させない
        base = match_value[2:]
        return host != base and host.endswith("." + base)

    def replace_host(parsed, new_host):
        """
        ホストだけを置き換え、ユーザー情報とポートは維持する。
        """
        netloc = parsed.netloc

        # ユーザー情報を分離
        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
            userinfo += "@"
        else:
            userinfo = ""
            hostport = netloc

        # 元のポート表記を維持
        port_suffix = ""
        if hostport.startswith("["):
            # IPv6形式
            closing = hostport.find("]")
            if closing != -1:
                port_suffix = hostport[closing + 1:]
        else:
            colon = hostport.rfind(":")
            if colon != -1:
                port_suffix = hostport[colon:]

        # IPv6アドレスを action_value に指定した場合にも対応
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = userinfo + new_host + port_suffix
        return parsed._replace(netloc=new_netloc)

    result = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten = parsed
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            is_match = False

            if match_type == "path_prefix":
                is_match = parsed.path.startswith(match_value)

            elif match_type == "host":
                is_match = host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                query_names = {
                    name
                    for name, _ in parse_qsl(
                        parsed.query,
                        keep_blank_values=True
                    )
                }
                is_match = match_value in query_names

            if not is_match:
                continue

            # 最初に適合したルールだけを適用
            matched = True

            if action == "block":
                rewritten = None
                break

            action_value = rule["action_value"]

            if action == "strip_prefix":
                path = parsed.path
                if path.startswith(action_value):
                    path = path[len(action_value):]
                if path == "":
                    path = "/"

                rewritten = parsed._replace(path=path)

            elif action == "redirect_host":
                rewritten = replace_host(parsed, action_value)

            elif action == "add_query_param":
                if parsed.query:
                    query = parsed.query + "&" + action_value
                else:
                    query = action_value

                rewritten = parsed._replace(query=query)

            break

        if rewritten is None:
            result.append(None)
        else:
            result.append(urlunsplit(rewritten))

    return result
